#include "maidionis/model.h"
#include <torch/torch.h>
#include <filesystem>
#include <fstream>
#include <sstream>
#include <iostream>
#include <random>
#include <set>
#include <ctime>
#include <fcntl.h>
#include <unistd.h>
#include <cerrno>
using namespace maidionis;
namespace fs=std::filesystem;
// Rhythm-first timing tasks see only neutral tonic degree history (token183).
// Degree task sees prior degrees and the already-planned current rhythm.
// Independent arm retains prior pitch history: this is a documented confound.
const char* TASK="mousa.rhythm-first-comparison.experimental.v1";
std::string ARM;
void setarm(const Json& value){if(!value.is_string()||(value!="independent"&&value!="rhythm_first"))throw std::runtime_error("invalid arm");ARM=value.get<std::string>();}
const int sizes[]={192,48,48,49,4,2};
void check(bool ok,const std::string&s){if(!ok)throw std::runtime_error(s);}
std::string read(const fs::path&p){std::ifstream f(p,std::ios::binary|std::ios::ate);check(bool(f),"input unavailable");check(f.tellg()>=0&&f.tellg()<=32*1024*1024,"input size");f.seekg(0);std::ostringstream s;s<<f.rdbuf();return s.str();}
void write(const fs::path&p,const std::string&s){int fd=::open(p.c_str(),O_WRONLY|O_CREAT|O_EXCL,0600);check(fd>=0,"exclusive output failed");size_t i=0;while(i<s.size()){auto n=::write(fd,s.data()+i,s.size()-i);if(n<0&&errno==EINTR)continue;check(n>0,"write failed");i+=n;}check(::fsync(fd)==0,"fsync failed");check(::close(fd)==0,"close failed");}
int integer(const Json&v,int lo,int hi){check(v.is_number_integer()&&v.get<double>()>=lo&&v.get<double>()<=hi,"integer/range");return v.get<int>();}
ModelConfig config(){ModelConfig c;c.kind="encoder";c.hidden_width=256;c.input_width=2;c.output_width=192;c.vocabulary=462;c.controls={1,2,3,4,5,6};c.dropout_milli=0;return c;}
ModelConfig oldconfig(){auto c=config();c.output_width=49;c.vocabulary=77;c.controls={1,2};return c;}
void rowcheck(const Json&r){check(r.is_object(),"row object");for(auto it=r.begin();it!=r.end();++it)check(std::set<std::string>{"input","label","task","family","target_index"}.contains(it.key()),"unknown row key");int task=integer(r.at("task"),0,5);check(r.at("family").is_string()&&!r.at("family").get<std::string>().empty()&&r.at("family").get<std::string>().size()<=256,"family");if(r.contains("target_index"))integer(r.at("target_index"),8,10000000);auto&x=r.at("input");check(x.is_array()&&x.size()==54,"input length");check(integer(x[0],1,6)==task+1,"task token");int count=integer(x[1],7,70)-6;integer(x[2],71,118);const int lo[]={119,311,359,407,456,460},hi[]={310,358,406,455,459,461};for(int i=0;i<48;++i){int value=integer(x[3+i],lo[i%6],hi[i%6]);if(i%6==0)check((value-119)%64<count,"history degree outside scale");}for(int i=0;i<8;++i){int at=3+6*i;int ioi=x[at+1].get<int>()-311,dur=x[at+2].get<int>()-359,rest=x[at+3].get<int>()-407;check(dur<=ioi&&rest==ioi-dur,"history duration/rest relation");}check(ARM=="independent"||ARM=="rhythm_first","unset arm");if(ARM=="rhythm_first"&&task!=0){for(int i=0;i<8;++i)check(x[3+6*i].get<int>()==183,"rhythm-first timing requires neutral degree history");}if(ARM=="rhythm_first"&&task==0){int ioi=integer(x[51],311,358)-311,dur=integer(x[52],359,406)-359,rest=integer(x[53],407,455)-407;check(dur<=ioi&&rest==ioi-dur,"current duration/rest relation");}else{for(int i=51;i<54;++i)check(integer(x[i],0,0)==0,"unexpected current context");}int y=integer(r.at("label"),0,sizes[task]-1);if(task==0)check(y%64<count,"target degree outside scale");}
Batch batch(const Json&rows){check(rows.is_array()&&!rows.empty()&&rows.size()<=64,"batch bounds");std::vector<int64_t>x,y;for(auto&r:rows){rowcheck(r);for(auto&v:r.at("input"))x.push_back(v.get<int64_t>());y.push_back(r.at("label").get<int64_t>());}Batch b;b.inputs=torch::from_blob(x.data(),{int64_t(rows.size()),54},torch::kInt64).clone();b.targets=torch::from_blob(y.data(),{int64_t(rows.size())},torch::kInt64).clone();b.mask=b.inputs.ne(0);b.segments=torch::zeros_like(b.inputs);b.target_mask=torch::ones_like(b.targets,torch::kBool);return b;}
torch::Tensor logits(ModelPtr m,const Batch&b){auto z=m->forward(b);std::vector<torch::Tensor> masks;for(int64_t i=0;i<z.size(0);++i){int task=b.inputs[i][0].item<int>()-1,count=b.inputs[i][1].item<int>()-6;auto ids=torch::arange(192,b.inputs.options());masks.push_back(task==0?ids.remainder(64).ge(count):ids.ge(sizes[task]));}return z.masked_fill(torch::stack(masks),-1e9);}

Json part(const Json&r,size_t start,size_t n=32){Json p=Json::array();for(size_t i=start;i<std::min(start+n,r.size());++i)p.push_back(r[i]);return p;}
Json evaluate(ModelPtr m,const Json&rows,bool probs=false){m->eval();torch::NoGradGuard guard;Json result=Json::array();for(size_t i=0;i<rows.size();i+=32){auto p=part(rows,i);auto b=batch(p);auto z=logits(m,b),lp=torch::log_softmax(z,1),pr=torch::softmax(z.to(torch::kFloat64),1);for(size_t j=0;j<p.size();++j){int task=p[j].at("task"),y=p[j].at("label");Json out={{"family",p[j].at("family")},{"task",task},{"target",y},{"prediction",z[j].argmax().item<int>()},{"nll",-lp[j][y].item<double>()}};if(p[j].contains("target_index"))out["target_index"]=p[j]["target_index"];if(probs){out["probabilities"]=Json::array();for(int k=0;k<sizes[task];++k)out["probabilities"].push_back(pr[j][k].item<double>());}result.push_back(out);}}return result;}
std::string tsha(torch::Tensor t){t=t.detach().contiguous();return sha256(std::string(static_cast<const char*>(t.data_ptr()),t.numel()*t.element_size()));}
Json warmstart(ModelPtr m,const fs::path&dir){auto raw=read(dir/"manifest.json");auto mf=Json::parse(raw);check(mf.at("schema")=="mousa-offline-music-checkpoint-v1"&&mf.at("complete")==true&&mf.at("model_config")==oldconfig().json(),"legacy checkpoint identity");auto w=read(dir/"weights.pt");check(sha256(w)==mf.at("weights_sha256").get<std::string>(),"legacy weights digest");auto old=make_seeded_model(oldconfig(),42);load_model_bytes(old,w);Json copied=Json::array();auto source=old->named_parameters();torch::NoGradGuard guard;for(auto&p:m->named_parameters()){if(p.key()=="embedding.weight"||p.key()=="output.weight"||p.key()=="output.bias")continue;check(source.contains(p.key())&&source[p.key()].sizes()==p.value().sizes(),"transfer name/shape");p.value().copy_(source[p.key()]);check(torch::equal(p.value(),source[p.key()]),"transfer differs");copied.push_back({{"name",p.key()},{"shape",p.value().sizes().vec()},{"sha256",tsha(p.value())},{"elements",p.value().numel()}});}check(copied.size()==50,"unexpected transfer inventory");return {{"source_manifest_sha256",sha256(raw)},{"source_weights_sha256",sha256(w)},{"copied_parameters",copied},{"new_parameters",{"embedding.weight","output.weight","output.bias"}},{"optimizer","fresh AdamW; not a checkpoint resume"},{"semantic_caveat","backbone warm-start only; changed positions/token semantics; no preserved-quality claim"}};}
ModelPtr load(const fs::path&dir){auto mf=Json::parse(read(dir/"manifest.json"));check(mf.at("schema")=="mousa.rhythm-first-model.experimental.v1"&&mf.at("task_id")==TASK&&mf.at("complete")==true&&mf.at("model_config")==config().json(),"model identity");setarm(mf.at("arm"));auto w=read(dir/"weights.pt");check(sha256(w)==mf.at("weights_sha256").get<std::string>(),"weights digest");auto m=make_seeded_model(config(),314);load_model_bytes(m,w);return m;}
int main(int argc,char**argv){try{check(argc>=3,"train DATA OUT LEGACY | score MODEL REQUEST OUTPUT | serve MODEL");std::string mode=argv[1];auto start=std::clock();auto guard=[&]{check(double(std::clock()-start)/CLOCKS_PER_SEC<180,"180 CPU second budget");};if(mode=="train"){check(argc==5,"train DATA OUT LEGACY");auto raw=read(argv[2]);auto d=Json::parse(raw);check(d.is_object()&&d.size()==5&&d.at("schema")=="mousa.rhythm-first-training.experimental.v1"&&d.at("task_id")==TASK,"data schema");setarm(d.at("arm"));std::set<std::string>families;for(auto key:{"train","test"}){auto&r=d.at(key);check(r.is_array()&&!r.empty()&&r.size()<=16384,"dataset bounds");std::set<std::string>ids;for(auto&row:r){rowcheck(row);check(row.contains("target_index"),"training row identity required");auto f=row.at("family").get<std::string>();check(ids.insert(f+":"+row.at("target_index").dump()+":"+row.at("task").dump()).second,"duplicate identity");if(std::string(key)=="train")families.insert(f);else check(!families.contains(f),"train/eval family leakage");}}fs::path out=argv[3];check(!fs::exists(out),"output exists");auto m=make_seeded_model(config(),314);auto transfer=warmstart(m,argv[4]);std::string initial_inventory;for(auto&p:m->named_parameters())initial_inventory+=p.key()+":"+tsha(p.value())+"\n";auto before=m->named_parameters()["embedding.weight"].detach().clone();torch::optim::AdamW opt(m->parameters(),torch::optim::AdamWOptions(.0003).weight_decay(0));Json result={{"initial_parameter_inventory_sha256",sha256(initial_inventory)},{"arm",ARM},{"transfer",transfer},{"initial_test",evaluate(m,d.at("test"))},{"losses",Json::array()}};std::mt19937 rng(314);std::string schedule;for(int step=0;step<60;++step){guard();Json rows=Json::array();for(int i=0;i<32;++i){auto index=rng()%d.at("train").size();rows.push_back(d.at("train")[index]);schedule+=std::to_string(index)+",";}auto b=batch(rows);m->train();opt.zero_grad();auto loss=categorical_loss(logits(m,b),b.targets,b.target_mask);check(torch::isfinite(loss).item<bool>(),"nonfinite loss");loss.backward();for(auto&p:m->parameters())check(p.grad().defined()&&torch::isfinite(p.grad()).all().item<bool>(),"invalid gradient");torch::nn::utils::clip_grad_norm_(m->parameters(),1);opt.step();m->enforce_constraints();result["losses"].push_back(loss.item<double>());}guard();result["schedule_indices_sha256"]=sha256(schedule);result["final_test"]=evaluate(m,d.at("test"));result["embedding_delta_l1"]=(m->named_parameters()["embedding.weight"]-before).abs().sum().item<double>();check(result["embedding_delta_l1"].get<double>()>0,"no embedding update");auto w=save_model_bytes(m);auto reloaded=make_seeded_model(config(),999);load_model_bytes(reloaded,w);m->eval();reloaded->eval();{torch::NoGradGuard g;auto b=batch(part(d.at("train"),0));check(torch::equal(logits(m,b),logits(reloaded,b)),"reload logits mismatch");}result["reload_logits_exact"]=true;torch::serialize::OutputArchive oa;opt.save(oa);std::ostringstream os;oa.save_to(os);result["cpu_seconds"]=double(std::clock()-start)/CLOCKS_PER_SEC;guard();if(!out.parent_path().empty())fs::create_directories(out.parent_path());check(fs::create_directory(out),"output race");write(out/"weights.pt",w);write(out/"optimizer.pt",os.str());write(out/"results.json",result.dump(2)+"\n");Json mf={{"schema","mousa.rhythm-first-model.experimental.v1"},{"task_id",TASK},{"arm",ARM},{"complete",true},{"model_config",config().json()},{"weights_sha256",sha256(w)},{"optimizer_sha256",sha256(os.str())},{"results_sha256",sha256(read(out/"results.json"))},{"data_sha256",sha256(raw)},{"steps",60},{"seed",314},{"batch_size",32},{"train_rows",d.at("train").size()},{"test_rows",d.at("test").size()},{"environment",parse_json(numerical_environment())},{"transfer",transfer}};write(out/"manifest.json",mf.dump(2)+"\n");std::cout<<"trained 60 fixed steps\n";}else if(mode=="score"){check(argc==5,"score MODEL REQUEST OUTPUT");auto rows=Json::parse(read(argv[3]));check(rows.is_array()&&!rows.empty()&&rows.size()<=16384,"score rows bounds");auto m=load(argv[2]);for(auto&r:rows)rowcheck(r);write(argv[4],evaluate(m,rows,true).dump()+"\n");}else if(mode=="serve"){check(argc==3,"serve MODEL");auto m=load(argv[2]);std::string line;for(int query=0;std::getline(std::cin,line);++query){guard();check(query<2400&&line.size()<=1024*1024,"query limit");auto rows=Json::parse(line);check(rows.is_array()&&!rows.empty()&&rows.size()<=64,"query rows bounds");for(auto&r:rows)rowcheck(r);std::cout<<evaluate(m,rows,true).dump()<<std::endl;}}else check(false,"unknown command");return 0;}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 1;}}
